from fizzbuzz import fizzbuzz


class FizzBuzzTests(unittest.TestCase):
    def test_first_fifteen_values(self):
        self.assertEqual(
            fizzbuzz(15),
            [
                "1", "2", "Fizz", "4", "Buzz",
                "Fizz", "7", "8", "Fizz", "Buzz",
                "11", "Fizz", "13", "14", "FizzBuzz",
            ],
        )

    def test_one(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_zero(self):
        self.assertEqual(fizzbuzz(0), [])

    def test_negative_input(self):
        self.assertEqual(fizzbuzz(-5), [])

    def test_later_multiples_and_inclusive_endpoint(self):
        values = fizzbuzz(30)
        self.assertEqual(len(values), 30)
        self.assertEqual(values[17], "Fizz")
        self.assertEqual(values[19], "Buzz")
        self.assertEqual(values[28], "29")
        self.assertEqual(values[29], "FizzBuzz")
        self.assertTrue(all(isinstance(value, str) for value in values))


if __name__ == "__main__":
    unittest.main()
